using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTools
{
    /// <summary>Fetches data from an external JSON API endpoint.</summary>
    [McpServerTool, Description("Fetches JSON data from the specified URL.")]
    public static async Task<string> FetchJson(
        HttpClient httpClient,
        [Description("The absolute URL to fetch JSON from.")] string url,
        CancellationToken cancellationToken = default)
    {
        using var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a concise summary of the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional desired length: short, medium, or long.")] string length = "medium")
    {
        return
        [
            new(Role.User,
                $"Summarize the following text. Target length: {length}.\n\n{text}")
        ];
    }
}

